class PettyCashLedgerEntity31:
    """Data transfer object for Branch Petty Cash Expense Vouchers and Approval Workflow - Segment 31."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
