@dataclass
class PettyCashLedgerEntity33:
    """Data transfer object for Branch Petty Cash Expense Vouchers and Approval Workflow - Segment 33."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
